<!doctype html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#10251f">
<title>رفيقي الدراسي V3</title>
<style>
:root{--bg:#0b1512;--panel:#14231e;--panel2:#1b3028;--text:#f1f7f3;--muted:#a8bdb2;--green:#56d39b;--line:#29463a;--red:#ff8e8e;--gold:#f6ce72}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#10221b,var(--bg) 320px);color:var(--text);font-family:system-ui,-apple-system,"Segoe UI",Tahoma,Arial,sans-serif;min-height:100vh}header{padding:22px 16px 16px;background:#10251f;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}header h1{margin:0;font-size:24px}header p{margin:6px 0 0;color:var(--muted);font-size:13px}.wrap{max-width:900px;margin:auto;padding:14px 12px 90px}.tabs{display:flex;gap:8px;overflow:auto;padding:10px 0 14px;position:sticky;top:94px;background:var(--bg);z-index:4}.tab{border:1px solid var(--line);background:var(--panel);color:var(--text);padding:10px 13px;border-radius:14px;white-space:nowrap;font-size:14px}.tab.active{background:var(--green);color:#092017;border-color:var(--green);font-weight:800}.page{display:none}.page.active{display:block}.card{background:linear-gradient(145deg,var(--panel),#101d18);border:1px solid var(--line);border-radius:18px;padding:15px;margin-bottom:12px;box-shadow:0 8px 22px #0002}.card h2,.card h3{margin:0 0 12px}.card h2{font-size:18px}.card h3{font-size:16px}.muted{color:var(--muted);font-size:13px;line-height:1.7}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:var(--panel2);border-radius:14px;padding:13px}.stat b{display:block;font-size:24px;color:var(--green)}label{display:block;color:var(--muted);font-size:13px;margin:10px 0 5px}input,textarea,select{width:100%;padding:12px;border-radius:12px;border:1px solid var(--line);background:#0b1712;color:var(--text);font:inherit;outline:none}textarea{min-height:90px;resize:vertical}button{border:0;border-radius:12px;padding:11px 14px;background:var(--green);color:#082016;font-weight:800;font:inherit;cursor:pointer}button.secondary{background:var(--panel2);color:var(--text);border:1px solid var(--line)}button.danger{background:#492727;color:#ffdede}button:disabled{opacity:.55}.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.row>*{flex:1}.item{padding:12px;border:1px solid var(--line);border-radius:13px;margin-top:8px;background:#0d1a15}.item strong{display:block;margin-bottom:4px}.item small{color:var(--muted)}.answer{padding:10px;border:1px solid var(--line);border-radius:12px;margin:7px 0;cursor:pointer}.answer.chosen{border-color:var(--green);background:#1b382c}.notice{padding:10px;border-radius:12px;background:#1e352a;color:#d8f8e8;font-size:13px;line-height:1.7}.warning{background:#382f19;color:#ffebba}.result{white-space:pre-wrap;line-height:1.9;background:#0a1711;border:1px solid var(--line);border-radius:12px;padding:12px;margin-top:10px;overflow-wrap:anywhere}.hidden{display:none!important}.timer{font-size:42px;font-weight:900;text-align:center;padding:16px;color:var(--green);font-variant-numeric:tabular-nums}.progress{height:9px;background:#263d32;border-radius:99px;overflow:hidden;margin:8px 0}.progress span{display:block;height:100%;background:var(--green);width:0}.footer{text-align:center;color:var(--muted);font-size:12px;padding:20px 0}.pill{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:3px 8px;font-size:12px;color:var(--muted)}@media(min-width:700px){.grid{grid-template-columns:repeat(4,minmax(0,1fr))}.wrap{padding-top:20px}}
</style>
</head>
<body>
<header><h1>📗 رفيقي الدراسي <span class="pill">V3</span></h1><p>رفيقك للدروس، الكتب، المراجعة وهدف الإعفاء العام</p></header>
<div class="wrap">
<nav class="tabs" aria-label="التنقل">
<button class="tab active" data-page="home">الرئيسية</button><button class="tab" data-page="lessons">دروس اليوم</button><button class="tab" data-page="books">كتب PDF</button><button class="tab" data-page="study">جلسة دراسة</button><button class="tab" data-page="quiz">اختبر نفسك</button><button class="tab" data-page="grades">درجاتي</button><button class="tab" data-page="settings">الإعدادات</button>
</nav>
<section id="home" class="page active">
<div class="card"><h2>هلا بيك، بطل الكهرباء ⚡</h2><p class="muted">سجّل شنو أخذت بالمدرسة، اختار درساً وابدأ بخطوة صغيرة اليوم. بياناتك محفوظة على هذا الجهاز.</p><div class="row"><button onclick="go('lessons')">＋ سجّل درس اليوم</button><button class="secondary" onclick="go('study')">ابدأ جلسة دراسة</button></div></div>
<div class="grid"><div class="stat"><span class="muted">الدروس المسجّلة</span><b id="statLessons">0</b></div><div class="stat"><span class="muted">جلسات الدراسة</span><b id="statSessions">0</b></div><div class="stat"><span class="muted">مجموع الدراسة</span><b id="statTime">0 د</b></div><div class="stat"><span class="muted">الدرجات المسجّلة</span><b id="statGrades">0</b></div></div>
<div class="card"><h2>📌 خطة بسيطة لليوم</h2><div id="todayPlan" class="muted">سجّل دروسك من تبويب «دروس اليوم»، وبعدها اختار درساً للمراجعة.</div></div>
<div class="card"><h2>🔔 تذكير الساعة 12 ظهراً</h2><p class="muted">تگدر تفعّل التذكير داخل التطبيق. قد لا يظهر إذا كان المتصفح مغلقاً أو النظام منع الإشعارات؛ للتنبيه المضمون نحتاج نسخة أندرويد أصلية أو خدمة إشعارات.</p><button class="secondary" onclick="enableReminder()">تفعيل تذكير 12 ظهراً</button><div id="reminderStatus" class="muted"></div></div>
</section>
<section id="lessons" class="page">
<div class="card"><h2>🗒️ سجّل شنو أخذت اليوم</h2><label>المادة</label><select id="lessonSubject"><option>كهرباء</option><option>رياضيات</option><option>عربي</option><option>إنكليزي</option><option>فيزياء</option><option>كيمياء</option><option>حاسوب</option><option>إسلامية</option><option>أخرى</option></select><label>عنوان الدرس</label><input id="lessonTitle" placeholder="مثلاً: قانون أوم"><label>تفاصيل أو ملاحظات</label><textarea id="lessonNotes" placeholder="شنو شرح المدرس؟ شنو ما فهمت؟"></textarea><div class="row"><button onclick="addLesson()">حفظ الدرس</button><button class="secondary" onclick="loadLessonIntoAI()">اشرح آخر درس بالذكاء الاصطناعي</button></div></div>
<div class="card"><h2>سجل الدروس</h2><div id="lessonList" class="muted">ماكو دروس مسجلة لحد الآن.</div></div>
</section>
<section id="books" class="page">
<div class="card"><h2>📚 مكتبة الكتب PDF</h2><p class="muted">اختار كتاباً من جهازك. يحاول التطبيق قراءة النص من ملف PDF وتحديد صفحة لشرحها. بعض الملفات المصوّرة تحتاج OCR ولا يمكن استخراج نصها بهذه الطريقة.</p><label>اسم الكتاب</label><input id="bookName" placeholder="مثلاً: كهرباء ثاني مهني"><label>ملف PDF</label><input id="pdfFile" type="file" accept="application/pdf,.pdf"><div class="row"><button onclick="addBook()">إضافة الكتاب</button><button class="secondary" onclick="loadPdfLibrary()">تحميل قارئ PDF</button></div><div id="pdfStatus" class="muted"></div></div>
<div class="card"><h2>صفحة من كتابك</h2><label>الكتاب</label><select id="bookSelect"></select><label>رقم الصفحة</label><input id="pageNumber" type="number" min="1" value="1"><div class="row"><button onclick="extractPage()">استخراج الصفحة</button><button class="secondary" onclick="explainPage()">لخّص واشرح الصفحة</button></div><div id="pageText" class="result">النص المستخرج من الصفحة يظهر هنا.</div></div>
<div class="card"><h2>اسأل عن الصفحة</h2><textarea id="bookQuestion" placeholder="مثلاً: اشرحلي القانون خطوة خطوة وباللهجة العراقية"></textarea><button onclick="askAboutPage()">اسأل رفيقي</button><div id="bookAnswer" class="result hidden"></div><div id="bookList"></div></div>
</section>
<section id="study" class="page">
<div class="card"><h2>⏱️ مؤقّت الدراسة</h2><div class="timer" id="timer">00:00:00</div><label>المادة اللي تدرسها</label><select id="timerSubject"><option>كهرباء</option><option>رياضيات</option><option>عربي</option><option>إنكليزي</option><option>فيزياء</option><option>كيمياء</option><option>حاسوب</option><option>إسلامية</option><option>أخرى</option></select><label>شنو هدف الجلسة؟</label><input id="timerGoal" placeholder="مثلاً: أفهم مثالين من قانون أوم"><div class="row"><button id="timerStart" onclick="startTimer()">ابدأ</button><button class="secondary" onclick="pauseTimer()">إيقاف مؤقت</button><button class="secondary" onclick="finishTimer()">إنهاء وحفظ</button></div><p class="muted" id="timerMsg">ابدأ بعشرين دقيقة، وخذ استراحة قصيرة بعدها.</p></div>
<div class="card"><h2>مساعد الشرح</h2><label>المادة والموضوع</label><input id="studyTopic" placeholder="مثلاً: توصيل المقاومات على التوالي"><label>شنو تحتاج؟</label><select id="studyMode"><option value="explain">شرح من الصفر باللهجة العراقية</option><option value="summary">ملخص مرتب للحفظ</option><option value="examples">أمثلة محلولة خطوة خطوة</option><option value="plan">خطة مراجعة قصيرة</option></select><textarea id="studyExtra" placeholder="اكتب السؤال أو الصق نص الدرس هنا"></textarea><button onclick="studyHelp()">ساعدني أدرس</button><div id="studyAnswer" class="result hidden"></div></div>
</section>
<section id="quiz" class="page">
<div class="card"><h2>🧠 اختبر نفسك</h2><p class="muted">اكتب اسم المادة والدرس. الذكاء الاصطناعي ينشئ أسئلة إذا ضبطت مفتاح API، أو استخدم الأسئلة اليدوية أدناه.</p><label>المادة والدرس</label><input id="quizTopic" placeholder="مثلاً: قانون أوم - كهرباء"><label>نص الدرس (اختياري)</label><textarea id="quizSource" placeholder="الصق ملاحظاتك أو نص الصفحة"></textarea><div class="row"><button onclick="generateQuiz()">أنشئ اختباراً</button><button class="secondary" onclick="showQuickQuiz()">اختبار سريع تجريبي</button></div><div id="quizOutput" class="result hidden"></div></div>
<div class="card"><h2>🔁 مراجعة الدروس</h2><p class="muted">علّم الدرس كمراجع حتى تتابع شنو راجعت. حاول تراجع بعد يوم، وبعد 3 أيام، وبعد أسبوع.</p><div id="reviewList"></div></div>
</section>
<section id="grades" class="page">
<div class="card"><h2>🎯 درجاتي وهدف الإعفاء</h2><label>المادة</label><select id="gradeSubject"><option>كهرباء</option><option>رياضيات</option><option>عربي</option><option>إنكليزي</option><option>فيزياء</option><option>كيمياء</option><option>حاسوب</option><option>إسلامية</option><option>أخرى</option></select><label>اسم الامتحان</label><input id="gradeName" placeholder="شهري / نصف السنة / يومي"><label>الدرجة</label><input id="gradeValue" type="number" min="0" max="100" placeholder="مثلاً 85"><label>الدرجة الكاملة</label><input id="gradeMax" type="number" min="1" value="100"><button onclick="addGrade()">حفظ الدرجة</button><div id="gradeList"></div><p class="muted">ملاحظة: شروط الإعفاء تعتمد على التعليمات الرسمية ودرجات المدرسة؛ هذا القسم للتتبع والحساب فقط وليس تأكيداً للاستحقاق.</p></div>
</section>
<section id="settings" class="page">
<div class="card"><h2>⚙️ إعداد الذكاء الاصطناعي</h2><p class="muted">تحتاج اتصال إنترنت ومفتاح API متوافق حتى تعمل ميزات الشرح والتلخيص وإنشاء الاختبارات. المفتاح يُحفظ محلياً بهذا المتصفح؛ لا تشارك الملف أو جهازك إذا حفظت المفتاح عليه. قد توجد حدود استخدام أو تكاليف حسب مزوّد الخدمة.</p><label>رابط API (اختياري)</label><input id="apiUrl" placeholder="رابط endpoint متوافق مع OpenAI Chat Completions"><label>اسم النموذج</label><input id="apiModel" placeholder="اسم النموذج حسب مزوّد الخدمة"><label>مفتاح API</label><input id="apiKey" type="password" autocomplete="off" placeholder="ألصق المفتاح هنا"><div class="row"><button onclick="saveSettings()">حفظ الإعدادات</button><button class="secondary" onclick="testAI()">اختبار الاتصال</button></div><div id="aiStatus" class="muted"></div></div>
<div class="card"><h2>نسخة احتياطية</h2><p class="muted">نزّل نسخة من الدروس والدرجات والإعدادات النصية. ملفات PDF نفسها لا تدخل ضمن النسخة الاحتياطية.</p><div class="row"><button onclick="exportData()">تصدير البيانات</button><label style="margin:0"><input type="file" id="importFile" accept="application/json,.json" onchange="importData(event)"> استيراد نسخة احتياطية</label></div><button class="danger" onclick="clearData()">مسح بيانات التطبيق</button></div>
<div class="notice warning">تنبيه: هذه نسخة ويب محلية تجريبية وليست تطبيق أندرويد أصلياً. الإشعارات قد لا تعمل والمتصفح مغلق، والملفات الكبيرة قد لا تبقى محفوظة إذا مسحت بيانات المتصفح.</div>
</section>
<div class="footer">رفيقي الدراسي V3 • صنع للدراسة خطوة بخطوة ⚡</div>
</div>
<script>
const KEY='rafiqi_v3_data';
let db={lessons:[],sessions:[],grades:[],books:[],reviews:[],settings:{apiUrl:'',apiModel:'',apiKey:''}};
function load(){try{const d=JSON.parse(localStorage.getItem(KEY)||'null');if(d)db={...db,...d,settings:{...db.settings,...(d.settings||{})}}}catch(e){}}
function save(){localStorage.setItem(KEY,JSON.stringify(db));render()}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function go(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.page===id));window.scrollTo({top:0,behavior:'smooth'});if(id==='books')renderBooks();if(id==='quiz')renderReviews()}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
function addLesson(){let subject=document.getElementById('lessonSubject').value,title=document.getElementById('lessonTitle').value.trim(),notes=document.getElementById('lessonNotes').value.trim();if(!title){alert('اكتب عنوان الدرس أولاً');return}db.lessons.unshift({id:Date.now(),subject,title,notes,date:new Date().toLocaleDateString('en-CA'),reviewed:false});document.getElementById('lessonTitle').value='';document.getElementById('lessonNotes').value='';save();alert('انحفظ الدرس 👍')}
function removeLesson(id){if(confirm('تحذف هذا الدرس؟')){db.lessons=db.lessons.filter(x=>x.id!==id);save()}}
function loadLessonIntoAI(){if(!db.lessons.length){alert('سجّل درس أولاً');return}let l=db.lessons[0];document.getElementById('studyTopic').value=l.subject+' - '+l.title;document.getElementById('studyExtra').value=l.notes;go('study')}
let elapsed=0,startAt=null,interval=null;
function fmt(s){s=Math.floor(s);return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')}
function updateTimer(){let n=elapsed+(startAt?Math.floor((Date.now()-startAt)/1000):0);document.getElementById('timer').textContent=fmt(n)}
function startTimer(){if(startAt)return;startAt=Date.now();interval=setInterval(updateTimer,500);document.getElementById('timerMsg').textContent='الجلسة شغالة؛ ركّز على هدفك.'}
function pauseTimer(){if(!startAt)return;elapsed+=Math.floor((Date.now()-startAt)/1000);startAt=null;clearInterval(interval);interval=null;updateTimer();document.getElementById('timerMsg').textContent='توقفت مؤقتاً. اضغط ابدأ حتى تكمل.'}
function finishTimer(){if(startAt){elapsed+=Math.floor((Date.now()-startAt)/1000);startAt=null}clearInterval(interval);interval=null;if(elapsed<5){alert('ابدأ جلسة وادرس شوي قبل الحفظ');updateTimer();return}db.sessions.unshift({id:Date.now(),subject:document.getElementById('timerSubject').value,goal:document.getElementById('timerGoal').value.trim(),seconds:elapsed,date:new Date().toLocaleDateString('en-CA')});elapsed=0;updateTimer();document.getElementById('timerMsg').textContent='انحفظت الجلسة، أحسنت!';save()}
async function loadPdfLibrary(){if(window.pdfjsLib){document.getElementById('pdfStatus').textContent='قارئ PDF جاهز.';return}document.getElementById('pdfStatus').textContent='جارٍ تحميل قارئ PDF من الإنترنت...';let s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';s.onload=()=>{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';document.getElementById('pdfStatus').textContent='تم تحميل قارئ PDF.'};s.onerror=()=>document.getElementById('pdfStatus').textContent='تعذر تحميل القارئ. تحقق من الإنترنت.';document.head.appendChild(s)}
async function addBook(){let f=document.getElementById('pdfFile').files[0],name=document.getElementById('bookName').value.trim()||f?.name;if(!f){alert('اختار ملف PDF');return}if(f.size>12*1024*1024){alert('الملف أكبر من 12MB لهذه النسخة. جرّب ملفاً أصغر حتى ما تمتلئ مساحة المتصفح.');return}try{const data=await f.arrayBuffer();if(!window.pdfjsLib)await new Promise((res,rej)=>{if(window.pdfjsLib)return res();let s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';s.onload=()=>{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';res()};s.onerror=rej;document.head.appendChild(s)});let pdf=await pdfjsLib.getDocument({data}).promise;let book={id:Date.now(),name,pages:pdf.numPages,buffer:Array.from(new Uint8Array(data)),added:new Date().toLocaleDateString('en-CA')};db.books.push(book);save();document.getElementById('pdfStatus').textContent=`تمت إضافة ${name} (${pdf.numPages} صفحة).`;document.getElementById('pdfFile').value='';document.getElementById('bookName').value='';}catch(e){console.error(e);alert('ما كدرنا نقرأ الملف. تأكد أنه PDF سليم وحاول مرة ثانية.')}}
function renderBooks(){let sel=document.getElementById('bookSelect'),old=sel.value;sel.innerHTML=db.books.map(b=>`<option value="${b.id}">${esc(b.name)} (${b.pages} صفحة)</option>`).join('');if(old)sel.value=old;document.getElementById('bookList').innerHTML=db.books.map(b=>`<div class="item"><strong>📘 ${esc(b.name)}</strong><small>${b.pages} صفحة • أضيف ${esc(b.added)}</small><div class="row"><button class="secondary" onclick="deleteBook(${b.id})">حذف الكتاب</button></div></div>`).join('')||'<p class="muted">ما ضفت كتب لحد الآن.</p>'}
function deleteBook(id){if(confirm('تحذف الكتاب من المكتبة؟')){db.books=db.books.filter(b=>b.id!==id);save();renderBooks()}}
let currentPageText='';
async function extractPage(){let id=Number(document.getElementById('bookSelect').value),b=db.books.find(x=>x.id===id),n=Number(document.getElementById('pageNumber').value);if(!b){alert('أضف كتاب PDF أولاً');return}if(!window.pdfjsLib){await loadPdfLibrary();if(!window.pdfjsLib){alert('تعذر تحميل قارئ PDF');return}}try{let pdf=await pdfjsLib.getDocument({data:new Uint8Array(b.buffer)}).promise;if(n<1||n>pdf.numPages){alert('رقم الصفحة خارج نطاق الكتاب');return}let page=await pdf.getPage(n),content=await page.getTextContent();currentPageText=content.items.map(i=>i.str).join(' ');document.getElementById('pageText').textContent=currentPageText||'ما طلع نص من الصفحة. يمكن الملف مصوّر ويحتاج OCR.';document.getElementById('bookAnswer').classList.add('hidden')}catch(e){alert('تعذر استخراج الصفحة')}}
async function explainPage(){if(!currentPageText){await extractPage();if(!currentPageText)return}document.getElementById('bookQuestion').value='لخّص الصفحة واشرحها من الصفر باللهجة العراقية، واستخرج التعاريف والقوانين والنقاط المهمة وأسئلة للمراجعة.';askAboutPage()}
async function askAboutPage(){if(!currentPageText){alert('استخرج الصفحة أولاً');return}let q=document.getElementById('bookQuestion').value.trim()||'اشرح النص بوضوح';await aiRequest('أنت رفيق دراسي لطالب ثاني مهني قسم كهرباء في العراق. اشرح بدقة وبلهجة عراقية مبسطة، لا تخترع معلومات غير موجودة، وميّز أي معلومة إضافية عن نص الكتاب.\\nالنص:\\n'+currentPageText+'\\nطلب الطالب: '+q,'bookAnswer')}
